  Lemma lg_chunks : forall x, In x (chunk_list st') <-> x = ch \/ In x (chunk_list st).
Proof.
ltac2:(KReplay.run1 (kr_t_AG_LargeModel ()) ["WFLarge"] "p,3INlo"). Qed.

